extends RefCounted
# All nodes share one Dictionary blackboard supplied by the caller.
enum Status { SUCCESS, FAILURE, RUNNING }

func tick(_blackboard: Dictionary, _delta: float) -> Status:
	return Status.FAILURE

func reset() -> void:
	pass
