s=s.replace('\\tawait test_full_sequence()\\n\\tawait test_hidden_player()\\n\\tawait test_hysteresis_zone()', '\\tfor selected in [Guard.Brain.FSM, Guard.Brain.BT]:\\n\\t\\tbrain = selected\\n\\t\\tprint(\"=== Brain: \", Guard.Brain.keys()[brain], \" ===\")\\n\\t\\tawait test_full_sequence()\\n\\t\\tawait test_hidden_player()\\n\\t\\tawait test_hysteresis_zone()')
p.write_text(s)
